                        </TouchableOpacity>
                      </View>
                      <View style={styles.datePickerCol}>
                        <Text style={styles.datePickerLabel}>Day</Text>
                        <TouchableOpacity
                          style={styles.dateDropdown}
                          onPress={() => { closePickers(); setShowDayPicker(!showDayPicker); }}
