                        >
                          <Text style={styles.dateDropdownText}>{selectedDay}</Text>
                          <ChevronDown color={Colors.accent} size={14} />
                        </TouchableOpacity>
                      </View>
                      <View style={styles.datePickerCol}>
                        <Text style={styles.datePickerLabel}>Year</Text>
                        <TouchableOpacity
                          style={styles.dateDropdown}
